-- P2P: Procure-to-Pay (8 risks, 12 controls)
-- ---------------------------------------------------------------------------
insert into public.icfr_templates (code, name, cycle, description, sort_order)
values ('P2P', 'Procure-to-Pay', 'Procure-to-Pay', 'Purchasing, goods/services receipt, supplier invoice processing, accounts payable and disbursements. Covers vendor master data, purchase requisition and order approval, three-way match, payment release and AP reconciliation.', 10)
on conflict (code) do update set
  name = excluded.name, cycle = excluded.cycle, description = excluded.description, sort_order = excluded.sort_order;

insert into public.icfr_template_items (template_id, kind, ref, title, description, assertions, control_type, nature, frequency, is_key, level, coso_component, linked_risk_refs, sort_order)
select t.id, i.* from public.icfr_templates t
cross join (values
  ('risk', 'R1', 'Purchases are made from unauthorized or fictitious vendors, or vendor master data (bank details) is changed without authorization, resulting in fraudulent or misdirected payments.', null, array['existence_occurrence', 'rights_obligations']::text[], null, null, null, null::boolean, null, null, null, 10),
  ('risk', 'R2', 'Purchase commitments are entered into without appropriate authorization or outside delegated authority limits.', null, array['existence_occurrence', 'accuracy']::text[], null, null, null, null::boolean, null, null, null, 20),
  ('risk', 'R3', 'Liabilities are recorded for goods or services not received, or at quantities/prices that do not agree to the purchase order and receipt.', null, array['existence_occurrence', 'accuracy', 'valuation_allocation']::text[], null, null, null, null::boolean, null, null, null, 30),
  ('risk', 'R4', 'Goods and services received before period end are not accrued, or invoices are recorded in the wrong period (unrecorded liabilities).', null, array['completeness', 'cutoff']::text[], null, null, null, null::boolean, null, null, null, 40),
  ('risk', 'R5', 'Duplicate invoices are processed and paid, or payments are released for invoices that were not approved.', null, array['existence_occurrence', 'accuracy']::text[], null, null, null, null::boolean, null, null, null, 50),
  ('risk', 'R6', 'Payments are released to the wrong payee, for the wrong amount, or without segregation between invoice approval and payment release.', null, array['existence_occurrence', 'accuracy']::text[], null, null, null, null::boolean, null, null, null, 60),
  ('risk', 'R7', 'Accounts payable sub-ledger does not agree to the general ledger, and supplier balances are not reconciled to supplier statements.', null, array['completeness', 'accuracy', 'existence_occurrence']::text[], null, null, null, null::boolean, null, null, null, 70),
  ('risk', 'R8', 'Expenses are coded to the wrong account, cost centre or capital/expense classification.', null, array['accuracy', 'presentation_disclosure']::text[], null, null, null, null::boolean, null, null, null, 80),
  ('control', 'C1', 'Vendor master creation and change approval', 'New vendor set-up and changes to sensitive vendor master fields (name, bank account, tax registration, payment terms) are requested on a standard form with supporting documents (commercial registration, VAT certificate, bank letter), independently verified by Procurement via a call-back to a known contact, and approved by the AP Manager before the ERP change is released. The system generates a monthly vendor master change report that is reviewed by the Finance Manager for unauthorized changes.', null, 'preventive', 'it_dependent', 'event_driven', true, 'process', 'control_activities', array['R1', 'R6']::text[], 90),
  ('control', 'C2', 'Purchase requisition and PO approval workflow (DoA)', 'The ERP enforces a delegation-of-authority (DoA) workflow: purchase requisitions and purchase orders are routed to approvers based on value thresholds and cost centre, and cannot be released without the required approvals. The DoA matrix in the system is reconciled to the board-approved DoA policy annually.', null, 'preventive', 'automated', 'event_driven', true, 'process', 'control_activities', array['R2']::text[], 100),
  ('control', 'C3', 'Goods receipt recorded by independent receiving function', 'Goods receipt notes (GRN) are recorded in the ERP by warehouse/receiving staff who are independent of purchasing and AP, upon physical inspection of quantity and condition against the PO. Services receipt is confirmed by the requesting business owner in the system before invoice processing.', null, 'preventive', 'manual', 'multiple_daily', false, 'process', 'control_activities', array['R3']::text[], 110),
  ('control', 'C4', 'Automated three-way match', 'The ERP performs an automated three-way match of supplier invoice to PO and GRN on quantity and price within configured tolerances (e.g. 2% or SAR 500). Invoices outside tolerance are blocked for payment and routed to the buyer for resolution; blocked invoices over 30 days are reported to the AP Manager weekly.', null, 'preventive', 'automated', 'multiple_daily', true, 'process', 'control_activities', array['R3', 'R5']::text[], 120),
  ('control', 'C5', 'Non-PO invoice approval', 'Invoices without a purchase order (utilities, professional fees, rent) are approved by the budget holder per the DoA before posting, with the AP Supervisor verifying the approval evidence and account coding. Non-PO spend by category is reviewed monthly by the Finance Manager for reasonableness and policy compliance.', null, 'preventive', 'manual', 'daily', true, 'process', 'control_activities', array['R2', 'R3', 'R8']::text[], 130),
  ('control', 'C6', 'Duplicate invoice check', 'The ERP rejects invoice entry where the combination of vendor, invoice number and amount already exists. AP additionally runs a monthly fuzzy-match duplicate payment report (same vendor/amount within 30 days, similar invoice numbers) and investigates exceptions, recovering any duplicate payments.', null, 'preventive', 'automated', 'multiple_daily', true, 'process', 'control_activities', array['R5']::text[], 140),
  ('control', 'C7', 'Payment run review and release', 'The proposed payment run is generated from approved, due invoices only. The AP Supervisor reviews the payment proposal to supporting invoices for a sample and for all items above SAR 100,000, and the Treasury Manager (independent of AP) releases the bank file under dual authorization in the bank portal. Payment file totals are agreed to the ERP payment run.', null, 'preventive', 'it_dependent', 'weekly', true, 'process', 'control_activities', array['R5', 'R6']::text[], 150),
  ('control', 'C8', 'Unrecorded liabilities and GRNI accrual review', 'At month end, AP prepares an accrual for goods received not invoiced (GRNI report from ERP) and reviews post-period-end invoices and payments above SAR 20,000 to identify liabilities relating to the closed period. The Financial Controller reviews the accrual schedule, the ageing of GRNI items over 90 days, and the search for unrecorded liabilities, evidencing review by sign-off.', null, 'detective', 'manual', 'monthly', true, 'process', 'control_activities', array['R4']::text[], 160),
  ('control', 'C9', 'AP sub-ledger to general ledger reconciliation', 'The AP sub-ledger is reconciled to the GL control account monthly; reconciling items are explained, aged and cleared within 60 days. The reconciliation is prepared by the AP Accountant and reviewed and signed by the Financial Controller within 5 working days of month end.', null, 'detective', 'manual', 'monthly', true, 'process', 'control_activities', array['R7']::text[], 170),
  ('control', 'C10', 'Supplier statement reconciliation', 'Statements from the top 20 suppliers by spend and any supplier with disputed balances are reconciled to the AP sub-ledger quarterly. Differences are investigated and adjusted where valid; the reconciliation is reviewed by the AP Manager.', null, 'detective', 'manual', 'quarterly', false, 'process', 'control_activities', array['R4', 'R7']::text[], 180),
  ('control', 'C11', 'Segregation of duties in the P2P cycle', 'ERP role design prevents a single user from holding conflicting P2P access (vendor master maintenance, PO approval, GRN entry, invoice posting, payment release). Conflicts are analysed quarterly via an SoD ruleset report; any residual conflict is approved by the CFO with a documented mitigating control.', null, 'preventive', 'it_dependent', 'quarterly', true, 'process', 'control_activities', array['R1', 'R5', 'R6']::text[], 190),
  ('control', 'C12', 'Expense account coding review', 'AP staff code invoices to the GL account and cost centre indicated on the approved PO or requisition; the ERP restricts capital accounts to requisitions flagged as capex with an approved capital request number. The Management Accountant reviews the monthly expense variance by account and cost centre against budget and investigates variances above 10% and SAR 50,000.', null, 'detective', 'manual', 'monthly', false, 'process', 'control_activities', array['R8']::text[], 200)
) as i(kind, ref, title, description, assertions, control_type, nature, frequency, is_key, level, coso_component, linked_risk_refs, sort_order)
where t.code = 'P2P'
on conflict (template_id, ref) do update set
  kind = excluded.kind, title = excluded.title, description = excluded.description,
  assertions = excluded.assertions, control_type = excluded.control_type, nature = excluded.nature,
  frequency = excluded.frequency, is_key = excluded.is_key, level = excluded.level,
  coso_component = excluded.coso_component, linked_risk_refs = excluded.linked_risk_refs,
  sort_order = excluded.sort_order;

delete from public.icfr_template_items i
using public.icfr_templates t
where i.template_id = t.id and t.code = 'P2P'
  and i.ref not in ('R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'R7', 'R8', 'C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12');

