insert into public.icfr_templates (code, name, cycle, description, sort_order)
values ('O2C', 'Order-to-Cash', 'Order-to-Cash', 'Customer master data, credit management, order acceptance, delivery, invoicing, revenue recognition, accounts receivable, cash application and expected credit loss provisioning under IFRS 15 and IFRS 9.', 20)
on conflict (code) do update set
  name = excluded.name, cycle = excluded.cycle, description = excluded.description, sort_order = excluded.sort_order;

insert into public.icfr_template_items (template_id, kind, ref, title, description, assertions, control_type, nature, frequency, is_key, level, coso_component, linked_risk_refs, sort_order)
select t.id, i.* from public.icfr_templates t
cross join (values
  ('risk', 'R1', 'Sales are recorded for fictitious customers or for goods/services not delivered (or performance obligations not satisfied), overstating revenue.', null, array['existence_occurrence']::text[], null, null, null, null::boolean, null, null, null, 10),
  ('risk', 'R2', 'Deliveries or services performed are not invoiced, or invoices are issued at incorrect prices, quantities or discounts.', null, array['completeness', 'accuracy']::text[], null, null, null, null::boolean, null, null, null, 20),
  ('risk', 'R3', 'Revenue is recognized in the wrong period (early or late cut-off), including bill-and-hold, side agreements and pre-delivery invoicing around period end.', null, array['cutoff', 'existence_occurrence']::text[], null, null, null, null::boolean, null, null, null, 30),
  ('risk', 'R4', 'Credit is extended to customers beyond approved limits or to customers with poor credit standing, resulting in uncollectible receivables.', null, array['valuation_allocation']::text[], null, null, null, null::boolean, null, null, null, 40),
  ('risk', 'R5', 'Credit notes, returns and write-offs are processed without authorization, or are used to conceal cash misappropriation.', null, array['existence_occurrence', 'accuracy']::text[], null, null, null, null::boolean, null, null, null, 50),
  ('risk', 'R6', 'Cash receipts are misapplied, applied to the wrong customer account, or not recorded (lapping/teeming and lading).', null, array['completeness', 'accuracy', 'existence_occurrence']::text[], null, null, null, null::boolean, null, null, null, 60),
  ('risk', 'R7', 'The expected credit loss (ECL) allowance is not calculated in accordance with IFRS 9 or is based on inaccurate ageing data, misstating net receivables.', null, array['valuation_allocation']::text[], null, null, null, null::boolean, null, null, null, 70),
  ('risk', 'R8', 'Contracts with multiple performance obligations, variable consideration or significant financing components are not identified and revenue is misallocated.', null, array['accuracy', 'valuation_allocation', 'presentation_disclosure']::text[], null, null, null, null::boolean, null, null, null, 80),
  ('control', 'C1', 'Customer master and credit limit approval', 'New customers are created only after a completed onboarding form with commercial registration and KYC documents, a credit assessment (financial statements, credit bureau/SIMAH report where available, trade references) and credit limit approval per the DoA. Changes to customer master fields, including credit limits and payment terms, follow the same approval and are reviewed on a monthly change report by the Credit Manager.', null, 'preventive', 'it_dependent', 'event_driven', true, 'process', 'control_activities', array['R1', 'R4']::text[], 90),
  ('control', 'C2', 'Automated credit check at order entry', 'The ERP performs an automated credit check on sales order creation and release; orders that would exceed the customer''s approved credit limit or where the account has overdue balances beyond 60 days are blocked. Blocked orders can be released only by the Credit Manager (or CFO above SAR 500,000) with documented rationale.', null, 'preventive', 'automated', 'multiple_daily', true, 'process', 'control_activities', array['R4']::text[], 100),
  ('control', 'C3', 'Contract review and revenue recognition assessment (IFRS 15)', 'Contracts above SAR 1 million or with non-standard terms (multiple deliverables, variable consideration, rebates, extended payment terms, acceptance clauses) are reviewed by Financial Reporting using the five-step model checklist before revenue recognition; the assessment identifies performance obligations, allocates the transaction price and documents the timing of recognition. The checklist is approved by the Financial Controller.', null, 'preventive', 'manual', 'event_driven', true, 'process', 'control_activities', array['R8', 'R3']::text[], 110),
  ('control', 'C4', 'Invoicing triggered by proof of delivery / service acceptance', 'The ERP generates customer invoices automatically from delivery notes (goods) or from service confirmations approved by the customer or project manager (services), using prices and discounts from the approved price master and customer contract. Manual invoice creation and price overrides are restricted to the Billing Supervisor and reported monthly.', null, 'preventive', 'automated', 'multiple_daily', true, 'process', 'control_activities', array['R1', 'R2']::text[], 120),
  ('control', 'C5', 'Shipment-to-invoice completeness reconciliation', 'Billing reconciles delivery notes / service confirmations issued during the month to invoices raised, and investigates unbilled deliveries and any invoice without a matching delivery. The reconciliation is reviewed by the Revenue Accountant and open items older than 30 days are escalated to the Financial Controller.', null, 'detective', 'manual', 'monthly', true, 'process', 'control_activities', array['R2']::text[], 130),
  ('control', 'C6', 'Revenue cut-off review at period end', 'At each month end, Financial Reporting reviews deliveries and invoices five working days either side of the period end, sales orders shipped but not invoiced, invoices raised for undelivered goods, and any bill-and-hold arrangements, and posts cut-off adjustments as required. Deferred and accrued revenue schedules are reviewed and signed by the Financial Controller.', null, 'detective', 'manual', 'monthly', true, 'process', 'control_activities', array['R3']::text[], 140),
  ('control', 'C7', 'Credit note and write-off approval', 'Credit notes require a documented reason (return, pricing dispute, damaged goods) with supporting evidence, and are approved per the DoA (Sales Manager up to SAR 25,000; CFO above) by someone independent of the originating salesperson and of cash application. Bad debt write-offs require Credit Committee approval. A monthly credit note report by customer and reason is reviewed by the Financial Controller for unusual patterns.', null, 'preventive', 'manual', 'event_driven', true, 'process', 'control_activities', array['R5']::text[], 150),
  ('control', 'C8', 'Daily cash application and unapplied cash review', 'Receipts from bank statements are applied to customer invoices daily by the Cash Application team using remittance advices; unapplied and unidentified receipts are followed up with customers and cleared within 15 days. The Credit Manager reviews the unapplied cash report weekly.', null, 'detective', 'it_dependent', 'daily', false, 'process', 'control_activities', array['R6']::text[], 160),
  ('control', 'C9', 'AR sub-ledger to GL reconciliation', 'The AR sub-ledger is reconciled to the general ledger control account monthly. Reconciling items are aged and cleared within 60 days. Prepared by the AR Accountant and reviewed and signed by the Financial Controller within 5 working days of month end.', null, 'detective', 'manual', 'monthly', true, 'process', 'control_activities', array['R2', 'R6']::text[], 170),
  ('control', 'C10', 'Customer statement circulation and dispute follow-up', 'Statements of account are sent to all active customers monthly; disputes and unreconciled differences reported by customers are logged, investigated and resolved by the Credit team. Positive confirmations are obtained from the top 20 customers at year end.', null, 'detective', 'manual', 'monthly', false, 'process', 'information_communication', array['R1', 'R6']::text[], 180),
  ('control', 'C11', 'AR ageing review and ECL allowance (IFRS 9)', 'The Credit Manager reviews the AR ageing monthly, documents collection status on all balances over 90 days, and the Financial Reporting team calculates the expected credit loss allowance quarterly using the approved provision matrix (historical loss rates by ageing bucket, adjusted for forward-looking factors) plus specific provisions for disputed or legal cases. The ECL calculation and key assumptions are reviewed and approved by the CFO.', null, 'detective', 'manual', 'quarterly', true, 'process', 'control_activities', array['R7', 'R4']::text[], 190),
  ('control', 'C12', 'Segregation of duties in O2C', 'ERP roles prevent the same user from maintaining customer master data, entering orders, issuing credit notes and applying cash. SoD conflicts are reviewed quarterly and any exception is approved by the CFO with a compensating control.', null, 'preventive', 'it_dependent', 'quarterly', true, 'process', 'control_activities', array['R5', 'R6']::text[], 200),
  ('control', 'C13', 'Sales price master maintenance', 'Changes to price lists, discount structures and promotional pricing are approved by the Commercial Director and uploaded by a restricted Sales Operations role; the ERP retains an audit log of price changes reviewed monthly by Finance for unauthorized changes.', null, 'preventive', 'it_dependent', 'event_driven', false, 'process', 'control_activities', array['R2']::text[], 210)
) as i(kind, ref, title, description, assertions, control_type, nature, frequency, is_key, level, coso_component, linked_risk_refs, sort_order)
where t.code = 'O2C'
on conflict (template_id, ref) do update set
  kind = excluded.kind, title = excluded.title, description = excluded.description,
  assertions = excluded.assertions, control_type = excluded.control_type, nature = excluded.nature,
  frequency = excluded.frequency, is_key = excluded.is_key, level = excluded.level,
  coso_component = excluded.coso_component, linked_risk_refs = excluded.linked_risk_refs,
  sort_order = excluded.sort_order;

delete from public.icfr_template_items i
using public.icfr_templates t
where i.template_id = t.id and t.code = 'O2C'
  and i.ref not in ('R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'R7', 'R8', 'C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12', 'C13');

